-- ============================================================
-- Migration 178 -- IELTS Academic Crash Course, Class 2: a listening class (lessons + quiz, then Listening Test 1)
--
-- Generated by database/quizzes/build_ielts_aca_crash_class2.py -- edit that, not this file.
-- Founder, 2026-10-28: a class is two hours -- "a lesson or more and then a quiz ... first hour, then a practice test
-- as the item for the second hour". The course had Listening Test 1 in Class 2 with no listening teaching before it
-- (the order was copied from the 2-Month Masterclass in 134 and patched since, never designed). Class 2 becomes:
--   1 IELTS Listening: Overview          lesson  (the founder's LISTENING_OVERVIEW video + the test's format/marking)
--   2 Listening Question Types           lesson  (LISTENING_QUESTION_TYPES video + a guide, with a practice)
--   3 Form Completion & Gap-fill         lesson  (SL1 deck + its recording: predict-the-gap and Jason's form)
--   4 Multiple Choice                    lesson  (SL5 deck + its recording: underline, paraphrase, Questions 1-4)
--   5 Class 2 Listening Quiz             quiz    (IELTS_ACA_C2_LQUIZ, 20 questions, pass 70%)
--   6 Listening Test 1                   practice test (unchanged)
-- Writing Task Overview leaves Class 2 for Week 3's first class (Class 5), straight before Writing Test 1 (Timed), as
-- the Masterclasses did in 157 -- only where that class holds Writing Test 1; otherwise it stays.
-- Found by folder + week + class, never by id; class ids kept (progress stays). Positions are parked at +100 first
-- (lesson_parts is unique on lesson_id + part_order). Re-runnable. MySQL 5.7-safe, no information_schema.
-- Needs the files: courses/IELTS_Aca_1Mo/lessons/class02_p1..p4_*.php, class05_p1_writing-task-overview.php,
-- listening_kit.php, assets/audio/ielts_listening_class2/, assets/video/ielts_listening/. The SELECT at the end lists
-- Class 2 and Class 5.
-- ============================================================

SET NAMES utf8mb4;

-- ---------------- The quiz ----------------
UPDATE questions x JOIN tests t ON t.id = x.test_id SET x.question_text = 'How many questions are there in the IELTS Listening test?' WHERE t.code = 'IELTS_ACA_C2_LQUIZ' AND x.question_number = 1;
UPDATE questions x JOIN tests t ON t.id = x.test_id SET x.question_text = 'How are the paper-based and computer-based Listening tests different?' WHERE t.code = 'IELTS_ACA_C2_LQUIZ' AND x.question_number = 2;
UPDATE questions x JOIN tests t ON t.id = x.test_id SET x.question_text = 'Which accents can you hear in the recordings?' WHERE t.code = 'IELTS_ACA_C2_LQUIZ' AND x.question_number = 3;
UPDATE questions x JOIN tests t ON t.id = x.test_id SET x.question_text = 'How long do you usually get to read the questions before each part starts?' WHERE t.code = 'IELTS_ACA_C2_LQUIZ' AND x.question_number = 4;
UPDATE questions x JOIN tests t ON t.id = x.test_id SET x.question_text = 'What has been true of the start of Part 1 since January 2020?' WHERE t.code = 'IELTS_ACA_C2_LQUIZ' AND x.question_number = 5;
UPDATE questions x JOIN tests t ON t.id = x.test_id SET x.question_text = 'What do you hear in Part 1?' WHERE t.code = 'IELTS_ACA_C2_LQUIZ' AND x.question_number = 6;
UPDATE questions x JOIN tests t ON t.id = x.test_id SET x.question_text = 'What do you hear in Part 2?' WHERE t.code = 'IELTS_ACA_C2_LQUIZ' AND x.question_number = 7;
UPDATE questions x JOIN tests t ON t.id = x.test_id SET x.question_text = 'What do you hear in Part 3?' WHERE t.code = 'IELTS_ACA_C2_LQUIZ' AND x.question_number = 8;
UPDATE questions x JOIN tests t ON t.id = x.test_id SET x.question_text = 'What do you hear in Part 4?' WHERE t.code = 'IELTS_ACA_C2_LQUIZ' AND x.question_number = 9;
UPDATE questions x JOIN tests t ON t.id = x.test_id SET x.question_text = 'In the paper-based test, what happens after the last recording?' WHERE t.code = 'IELTS_ACA_C2_LQUIZ' AND x.question_number = 10;
UPDATE questions x JOIN tests t ON t.id = x.test_id SET x.question_text = 'In the computer-based test, when can you review your answers?' WHERE t.code = 'IELTS_ACA_C2_LQUIZ' AND x.question_number = 11;
UPDATE questions x JOIN tests t ON t.id = x.test_id SET x.question_text = 'A multiple-choice question has more than three options. What must you do first?' WHERE t.code = 'IELTS_ACA_C2_LQUIZ' AND x.question_number = 12;
UPDATE questions x JOIN tests t ON t.id = x.test_id SET x.question_text = 'In plan, map or diagram labelling, what do you usually do?' WHERE t.code = 'IELTS_ACA_C2_LQUIZ' AND x.question_number = 13;
UPDATE questions x JOIN tests t ON t.id = x.test_id SET x.question_text = 'The instructions say "NO MORE THAN TWO WORDS AND/OR A NUMBER". What happens if you write three words?' WHERE t.code = 'IELTS_ACA_C2_LQUIZ' AND x.question_number = 14;
UPDATE questions x JOIN tests t ON t.id = x.test_id SET x.question_text = 'How is a hyphenated word such as "long-term" counted?' WHERE t.code = 'IELTS_ACA_C2_LQUIZ' AND x.question_number = 15;
UPDATE questions x JOIN tests t ON t.id = x.test_id SET x.question_text = 'You are not sure of an answer. What should you do?' WHERE t.code = 'IELTS_ACA_C2_LQUIZ' AND x.question_number = 16;
UPDATE questions x JOIN tests t ON t.id = x.test_id SET x.question_text = 'Before a form-completion task, what should you do in the reading time?' WHERE t.code = 'IELTS_ACA_C2_LQUIZ' AND x.question_number = 17;
UPDATE questions x JOIN tests t ON t.id = x.test_id SET x.question_text = 'A form row says "Mobile: ____" and a sentence says "Jason''s mobile phone number is ____". What is true?' WHERE t.code = 'IELTS_ACA_C2_LQUIZ' AND x.question_number = 18;
UPDATE questions x JOIN tests t ON t.id = x.test_id SET x.question_text = 'In a multiple-choice question, what will you hear in the recording?' WHERE t.code = 'IELTS_ACA_C2_LQUIZ' AND x.question_number = 19;
UPDATE questions x JOIN tests t ON t.id = x.test_id SET x.question_text = 'Which keywords are best to underline in "John Lancer''s idea for a cookery school came from"?' WHERE t.code = 'IELTS_ACA_C2_LQUIZ' AND x.question_number = 20;
DELETE o FROM question_options o JOIN questions x ON x.id = o.question_id JOIN tests t ON t.id = x.test_id WHERE t.code = 'IELTS_ACA_C2_LQUIZ' AND x.question_number > 20;
DELETE x FROM questions x JOIN tests t ON t.id = x.test_id WHERE t.code = 'IELTS_ACA_C2_LQUIZ' AND x.question_number > 20;

-- ---------------- Class 2 (Week 1, second class) ----------------
-- The classes, as variables (a scalar subquery, no derived tables). NULL on a course without them: every statement
-- below then matches nothing.
SET @c2 := (SELECT l.id FROM lessons l JOIN modules m ON m.id = l.module_id JOIN courses c ON c.id = l.course_id WHERE c.folder_name = 'IELTS_Aca_1Mo' AND m.module_order = 1 AND l.lesson_order = 2);
SET @c5 := (SELECT l.id FROM lessons l JOIN modules m ON m.id = l.module_id JOIN courses c ON c.id = l.course_id WHERE c.folder_name = 'IELTS_Aca_1Mo' AND m.module_order = 3 AND l.lesson_order = 1);
-- Class 5 only takes Writing Task Overview if it holds Writing Test 1.
SET @c5ok := (SELECT COUNT(*) FROM lesson_parts WHERE lesson_id = @c5 AND title = 'Writing Test 1 (Timed)');

-- Writing Task Overview: Class 2 -> Class 5, first item (Class 5's items move one place down, via +100).
UPDATE lesson_parts SET part_order = part_order + 100 WHERE lesson_id = @c5 AND @c5ok > 0 AND part_order < 100
   AND EXISTS (SELECT 1 FROM (SELECT lesson_id, title FROM lesson_parts) y WHERE y.lesson_id = @c2 AND y.title = 'Writing Task Overview');
UPDATE lesson_parts SET lesson_id = @c5, part_order = 1, file_path = 'courses/IELTS_Aca_1Mo/lessons/class05_p1_writing-task-overview.php'
 WHERE lesson_id = @c2 AND title = 'Writing Task Overview' AND @c5ok > 0;
UPDATE lesson_parts SET part_order = part_order - 99 WHERE lesson_id = @c5 AND part_order > 100;

-- Class 2's other items park at +100, Listening Test 1 then takes place 6.
UPDATE lesson_parts SET part_order = part_order + 100 WHERE lesson_id = @c2 AND part_order < 100;
UPDATE lesson_parts SET part_order = 6 WHERE lesson_id = @c2 AND title = 'Listening Test 1';
UPDATE lesson_parts SET part_order = 1, kind = 'lesson', status = 'ready', file_path = 'courses/IELTS_Aca_1Mo/lessons/class02_p1_ielts-listening-overview.php', test_code = NULL, pass_percent = NULL WHERE lesson_id = @c2 AND title = 'IELTS Listening: Overview';
SELECT @c2, 1, 'IELTS Listening: Overview', 'lesson', 'ready', 'courses/IELTS_Aca_1Mo/lessons/class02_p1_ielts-listening-overview.php', NULL, NULL FROM DUAL
 WHERE @c2 IS NOT NULL AND NOT EXISTS (SELECT 1 FROM (SELECT lesson_id, title FROM lesson_parts) y WHERE y.lesson_id = @c2 AND y.title = 'IELTS Listening: Overview');
UPDATE lesson_parts SET part_order = 2, kind = 'lesson', status = 'ready', file_path = 'courses/IELTS_Aca_1Mo/lessons/class02_p2_listening-question-types.php', test_code = NULL, pass_percent = NULL WHERE lesson_id = @c2 AND title = 'Listening Question Types';
SELECT @c2, 2, 'Listening Question Types', 'lesson', 'ready', 'courses/IELTS_Aca_1Mo/lessons/class02_p2_listening-question-types.php', NULL, NULL FROM DUAL
 WHERE @c2 IS NOT NULL AND NOT EXISTS (SELECT 1 FROM (SELECT lesson_id, title FROM lesson_parts) y WHERE y.lesson_id = @c2 AND y.title = 'Listening Question Types');
UPDATE lesson_parts SET part_order = 3, kind = 'lesson', status = 'ready', file_path = 'courses/IELTS_Aca_1Mo/lessons/class02_p3_form-completion-gap-fill.php', test_code = NULL, pass_percent = NULL WHERE lesson_id = @c2 AND title = 'Form Completion & Gap-fill';
SELECT @c2, 3, 'Form Completion & Gap-fill', 'lesson', 'ready', 'courses/IELTS_Aca_1Mo/lessons/class02_p3_form-completion-gap-fill.php', NULL, NULL FROM DUAL
 WHERE @c2 IS NOT NULL AND NOT EXISTS (SELECT 1 FROM (SELECT lesson_id, title FROM lesson_parts) y WHERE y.lesson_id = @c2 AND y.title = 'Form Completion & Gap-fill');
UPDATE lesson_parts SET part_order = 4, kind = 'lesson', status = 'ready', file_path = 'courses/IELTS_Aca_1Mo/lessons/class02_p4_multiple-choice.php', test_code = NULL, pass_percent = NULL WHERE lesson_id = @c2 AND title = 'Multiple Choice';
SELECT @c2, 4, 'Multiple Choice', 'lesson', 'ready', 'courses/IELTS_Aca_1Mo/lessons/class02_p4_multiple-choice.php', NULL, NULL FROM DUAL
 WHERE @c2 IS NOT NULL AND NOT EXISTS (SELECT 1 FROM (SELECT lesson_id, title FROM lesson_parts) y WHERE y.lesson_id = @c2 AND y.title = 'Multiple Choice');
UPDATE lesson_parts SET part_order = 5, kind = 'quiz', status = 'ready', file_path = 'resources/quizzes/class_quiz.php?test_code=IELTS_ACA_C2_LQUIZ', test_code = 'IELTS_ACA_C2_LQUIZ', pass_percent = 70 WHERE lesson_id = @c2 AND title = 'Class 2 Listening Quiz';
SELECT @c2, 5, 'Class 2 Listening Quiz', 'quiz', 'ready', 'resources/quizzes/class_quiz.php?test_code=IELTS_ACA_C2_LQUIZ', 'IELTS_ACA_C2_LQUIZ', 70 FROM DUAL
 WHERE @c2 IS NOT NULL AND NOT EXISTS (SELECT 1 FROM (SELECT lesson_id, title FROM lesson_parts) y WHERE y.lesson_id = @c2 AND y.title = 'Class 2 Listening Quiz');
-- Anything else still parked in Class 2 (an item this migration doesn't know) goes after the test, in its order.
UPDATE lesson_parts SET part_order = part_order - 93 WHERE lesson_id = @c2 AND part_order > 100;

-- The classes' titles list their items (rendered by includes/lesson_title.php); Class 2 is now a listening class.
UPDATE lessons SET title = 'IELTS Listening: Overview + Listening Question Types + Form Completion & Gap-fill + Multiple Choice + Class 2 Listening Quiz + Listening Test 1', icon = 'bi-headphones', duration_minutes = 120 WHERE id = @c2;
UPDATE lessons SET title = (SELECT GROUP_CONCAT(p.title ORDER BY p.part_order SEPARATOR ' + ') FROM lesson_parts p WHERE p.lesson_id = @c5) WHERE id = @c5 AND @c5ok > 0;

SELECT CASE WHEN p.lesson_id = @c2 THEN 'Class 2' ELSE 'Class 5' END AS class, p.part_order, p.title, p.kind, p.status, p.file_path
  FROM lesson_parts p WHERE p.lesson_id IN (@c2, @c5) ORDER BY p.lesson_id = @c5, p.part_order;
SELECT COUNT(*) AS quiz_questions FROM questions x JOIN tests t ON t.id = x.test_id WHERE t.code = 'IELTS_ACA_C2_LQUIZ';
